static_checks.command:
$capPath='D:\3\BOSDev\qa-scratch\bos3-guided-contract-20260930\writer\SESSION_CAPABILITIES.json'
$proposalPath='D:\3\BOSDev\evidence\product-enablement-20260930\GUIDED_LEARNING_CONTRACT_UA.json'
$cap=Get-Content -LiteralPath $capPath -Raw | ConvertFrom-Json
$proposal=Get-Content -LiteralPath $proposalPath -Raw | ConvertFrom-Json
if(Compare-Object @($proposal.lesson_fields) @($cap.lesson_fields.field)){throw 'lesson field coverage mismatch'}
if(Compare-Object @($proposal.step_fields) @($cap.step_fields.field)){throw 'step field coverage mismatch'}
if($cap.session_requirements.Count -ne $proposal.session_requirements.Count){throw 'session requirement count mismatch'}
$rows=@($cap.lesson_fields)+@($cap.step_fields)+@($cap.session_requirements)
foreach($row in $rows){if($row.status -notin @('exists','partial','implementation_gap')){throw 'invalid classification'}; if(!$row.evidence){throw 'missing evidence'}}
$hashes=@{}
$lineCounts=@{}
foreach($f in $cap.source_files){$hashes[$f.file]=(Get-FileHash -LiteralPath $f.path -Algorithm SHA256).Hash.ToLower();$lineCounts[$f.file]=(Get-Content -LiteralPath $f.path).Count;if($hashes[$f.file] -ne $f.sha256){throw ('source hash mismatch '+$f.file)}}
$sections=@('lesson_fields','step_fields','session_requirements','rights_and_ownership','persistence_contract','lifecycle','case_capabilities','kind_mapping','gaps')
$evidenceCount=0
foreach($section in $sections){foreach($row in $cap.$section){foreach($e in $row.evidence){if($e.file_sha256 -ne $hashes[$e.file]){throw ('evidence hash mismatch '+$e.file)};if($e.line_start -lt 1 -or $e.line_end -lt $e.line_start -or $e.line_end -gt $lineCounts[$e.file]){throw ('bad line range '+$e.file)};$evidenceCount++}}}
if($cap.executions -ne 0 -or $cap.QA -ne 'NOT_RUN'){throw 'execution status changed'}
if(@($cap.readiness.PSObject.Properties | Where-Object {$_.Value -ne $false}).Count){throw 'readiness changed'}
$actualNames=@(Get-ChildItem -LiteralPath (Split-Path $capPath) -File | ForEach-Object {$_.Name})
if(Compare-Object @('SESSION_CAPABILITIES.json','AUTHOR_REPORT_UA.md') $actualNames){throw 'output allowlist mismatch'}
[pscustomobject]@{lesson_fields=$cap.lesson_fields.Count;step_fields=$cap.step_fields.Count;session_requirements=$cap.session_requirements.Count;source_hashes=$hashes.Count;evidence_refs=$evidenceCount;gaps=$cap.gaps.Count;status=$cap.status;executions=$cap.executions;QA=$cap.QA} | ConvertTo-Json -Compress
